'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var abs = require( '@stdlib/math/base/special/abs' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// VARIABLES //

var mgf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( mgf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof mgf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = mgf( NaN, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `sigma`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = mgf( 2.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 2.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 2.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the created function evaluates the MGF for Half-normal distribution', function test( t ) {
	var expected;
	var delta;
	var sigma;
	var tol;
	var x;
	var y;
	var i;

	expected = data.expected;
	x = data.t;
	sigma = data.sigma;

	for ( i = 0; i < x.length; i++ ) {
		y = mgf( x[i], sigma[i] );

		if ( expected[i] !== null ) {
			if ( y === expected[i] ) {
				t.strictEqual( y, expected[i], 'x: '+x[i]+', sigma: '+sigma[i]+', y: '+y+', expected: '+expected[i] );
			} else {
				delta = abs( y - expected[i] );
				tol = 700.0 * EPS * abs( expected[i] );
				t.ok( isAlmostSameValue( y, expected[i], 1500 ), 'within tolerance. x: '+x[ i ]+'. sigma: '+sigma[ i ]+'. y: '+y+'. E: '+expected[ i ]+'. Δ: '+delta+'. tol: '+tol+'.' );
			}
		}
	}
	t.end();
});
